SELECT c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_buy_potential, sm.sm_ship_mode_id, SUM(cs.cs_net_profit) AS total_net_profit, CASE WHEN SUM(cs.cs_net_profit) > 100000 THEN 'Platinum' WHEN SUM(cs.cs_net_profit) > 50000 THEN 'Gold' ELSE 'Silver' END AS profit_tier, RANK() OVER (PARTITION BY hd.hd_buy_potential ORDER BY SUM(cs.cs_net_profit) DESC) AS profit_rank FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_buy_potential, sm.sm_ship_mode_id HAVING SUM(cs.cs_net_profit) > 0 ORDER BY total_net_profit DESC LIMIT 20
